func TestConfirmCancelledByContextCarriesTheContextsCause(t *testing.T) {
	t.Setenv(EnvAccessible, "")

	ctx, cancel := context.WithCancel(t.Context())
	cancel()

	_, err := Confirm(ctx, strings.NewReader(""), &bytes.Buffer{}, "Proceed?", true)

